-- 1. Enable Required Extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- 2. Clean Existing Tables (if re-running)
DROP TABLE IF EXISTS public.enrollment_applications CASCADE;
DROP TABLE IF EXISTS public.class_schedules CASCADE;
DROP TABLE IF EXISTS public.course_subjects CASCADE;
DROP TABLE IF EXISTS public.students CASCADE;
DROP TABLE IF EXISTS public.teachers CASCADE;
DROP TABLE IF EXISTS public.sections CASCADE;
DROP TABLE IF EXISTS public.classrooms CASCADE;
DROP TABLE IF EXISTS public.users CASCADE;
DROP TABLE IF EXISTS public.academic_terms CASCADE;
DROP TABLE IF EXISTS public.system_settings CASCADE;

-- 3. Create Schema Tables
CREATE TABLE public.academic_terms (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    "schoolYear" VARCHAR(20) NOT NULL,
    "termNumber" INT NOT NULL CHECK ("termNumber" IN (1, 2, 3)),
    "termName" VARCHAR(50) NOT NULL,
    "totalClassDays" INT,
    "startDate" DATE,
    "endDate" DATE,
    "openingBlockStart" DATE,
    "openingBlockEnd" DATE,
    "instructionalStart" DATE,
    "instructionalEnd" DATE,
    "endOfTermStart" DATE,
    "endOfTermEnd" DATE,
    "summative1Date" DATE,
    "summative2Date" DATE,
    "termExamDates" VARCHAR(100),
    "reportCardDate" DATE,
    "isActive" BOOLEAN DEFAULT FALSE,
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT unique_sy_term UNIQUE ("schoolYear", "termNumber")
);

CREATE TABLE public.classrooms (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    classroom_id VARCHAR(50) UNIQUE NOT NULL,
    room_name TEXT NOT NULL,
    building TEXT NOT NULL,
    capacity INT DEFAULT 40,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.sections (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    section_name TEXT NOT NULL,
    grade_level INT NOT NULL,
    strand TEXT,
    capacity INT DEFAULT 40,
    school_year TEXT,
    section_id TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.course_subjects (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    subject_code VARCHAR(50) UNIQUE NOT NULL,
    subject_name TEXT NOT NULL,
    subject_type VARCHAR(50),
    grade_level INT NOT NULL,
    trimester INT NOT NULL,
    strand TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.users (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    user_role VARCHAR(50) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.teachers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    teacher_id VARCHAR(50) UNIQUE NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    middle_name VARCHAR(100),
    last_name VARCHAR(100) NOT NULL,
    department VARCHAR(50),
    email VARCHAR(150),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.students (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    student_id VARCHAR(50) UNIQUE NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    middle_name VARCHAR(100),
    last_name VARCHAR(100) NOT NULL,
    date_of_birth DATE,
    gender VARCHAR(20),
    contact_number VARCHAR(50),
    barangay VARCHAR(100),
    grade_level INT NOT NULL,
    strand TEXT,
    is_returning BOOLEAN DEFAULT FALSE,
    current_section_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.enrollment_applications (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    application_id VARCHAR(50) UNIQUE NOT NULL,
    student_id UUID REFERENCES public.students(id) ON DELETE CASCADE,
    applicant_type TEXT,
    school_year TEXT,
    target_grade_level INT,
    target_strand TEXT,
    status TEXT DEFAULT 'Pending',
    submitted_documents JSONB DEFAULT '{}'::jsonb,
    selected_electives JSONB DEFAULT '[]'::jsonb,
    admin_feedback TEXT,
    reviewed_by TEXT,
    submission_date TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.class_schedules (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    schedule_code VARCHAR(100),
    section_id UUID REFERENCES public.sections(id) ON DELETE CASCADE,
    teacher_id UUID REFERENCES public.teachers(id) ON DELETE CASCADE,
    classroom_id UUID REFERENCES public.classrooms(id) ON DELETE SET NULL,
    subject_code VARCHAR(50),
    subject_name TEXT,
    day_of_week VARCHAR(20),
    start_time VARCHAR(20),
    end_time VARCHAR(20),
    school_year VARCHAR(20),
    trimester INT DEFAULT 1,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.system_settings (
    key VARCHAR(100) PRIMARY KEY,
    value JSONB NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS and permissive development policies
ALTER TABLE public.academic_terms ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.classrooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.teachers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enrollment_applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.class_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow all academic_terms" ON public.academic_terms FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all classrooms" ON public.classrooms FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all sections" ON public.sections FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all course_subjects" ON public.course_subjects FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all users" ON public.users FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all teachers" ON public.teachers FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all students" ON public.students FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all enrollment_applications" ON public.enrollment_applications FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all class_schedules" ON public.class_schedules FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all system_settings" ON public.system_settings FOR ALL USING (true) WITH CHECK (true);

-- Ensure Storage bucket for student documents exists
VALUES ('student-documents', 'student-documents', true, 10485760, NULL)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "Public Access student-documents" ON storage.objects
FOR ALL USING (bucket_id = 'student-documents') WITH CHECK (bucket_id = 'student-documents');

